import {loadGuardSize,saveGuardSize,configureCrew} from './crew-config.js';
import {CATALOG,defaultComposition,loadComposition,saveComposition,compositionErrors,signalChoices,signalZoneChoices} from './station-config.js';
const labels={standard:'Origine',short:'LED · rampe courte',wide:'LED · rampe large',round:'Ronds · rotatifs'};
export function openStationMenu(state,fleet,apply=()=>null,onBack=null){
 const dialog=document.createElement('dialog');dialog.className='stationComposer';document.body.append(dialog);const paused=state.paused;state.paused=true;state.composingStation=true;let rows=loadComposition(fleet)||defaultComposition(fleet),selected=0,guardSize=loadGuardSize();const slots=fleet.filter(e=>e.kind!=='VLCG');
 const finish=()=>{state.paused=paused;state.composingStation=false;dialog.remove();};dialog.addEventListener('close',finish,{once:true});
 function draw(){const r=rows[selected],info=CATALOG[r.type],errors=compositionErrors(rows),active=rows.filter(r=>r.type).length;dialog.innerHTML=`<div class="composerHead"><div><small>CONFIGURATION DU CENTRE</small><h2>Composer ma caserne</h2></div><button data-close aria-label="Fermer">×</button></div><p class="composerHint">Votre caserne · ${active} engins sur ${slots.length} places + votre VLCG · 50 personnels</p><label class="composerStaff">Garde au CIS <input data-staff type="number" min="4" max="30" value="${guardSize}"> / 50 <small>Capitaine et infirmier inclus · ${50-guardSize} SPV</small></label><div class="composerBody"><div class="composerSlots">${[['Sanitaire · remise dédiée',true],['Incendie et appui',false]].map(([name,medical])=>`<section><h3>${name}</h3><div class="slotGrid">${rows.map((v,i)=>(slots[i].home[0]>-70)===medical?`<button data-slot="${i}" aria-pressed="${i===selected}" class="${v.type?'':'emptySlot'}"><small>Place ${i+1}</small><b>${v.type?CATALOG[v.type].label:'＋ Ajouter un moyen'}</b></button>`:'').join('')}</div></section>`).join('')}<p class="composerHint">Retirez un engin pour libérer sa place, puis ajoutez le modèle souhaité. Chef de centre : VLCG conservée.</p></div><section class="composerEditor"><div class="vehicleSketch" aria-hidden="true"><svg viewBox="0 0 260 115"><rect x="${info?.group==='medical'?60:35}" y="30" width="180" height="55" rx="5" fill="${info?'#d53235':'#31494a'}"/><path d="M35 85V55l25-25h35v55Z" fill="${info?'#d53235':'#31494a'}"/><path d="M43 53 63 34h23v22H43Z" fill="#243b43"/><path d="M100 36h130v40H100Z" fill="${info?.group==='medical'?'#d53235':info?'#a6b6b3':'#40595a'}"/><path d="M36 68h200" stroke="${info?'#eddb43':'#6f8987'}" stroke-width="4"/><circle cx="65" cy="87" r="15" fill="#243035"/><circle cx="206" cy="87" r="15" fill="#243035"/>${info?['Front','Rear'].map((zone,i)=>{const choice=r['signal'+zone]||r.signal,cx=i?219:76;return choice==='round'?`<circle cx="${cx}" cy="24" r="6" fill="#56b3ed"/>`:`<rect x="${cx-(choice==='wide'?20:10)}" y="20" width="${choice==='wide'?40:20}" height="8" rx="2" fill="#56b3ed"/>`;}).join(''):''}</svg></div><small class="composerHint">Place ${selected+1} · ${info?'moyen installé':'emplacement libre'}</small><label>${info?'Remplacer ce moyen':'Ajouter un moyen'}<select data-type><option value="">${info?'Choisir un autre modèle':'Sélectionner un modèle'}</option>${Object.entries(CATALOG).filter(([,v])=>v.group===(slots[selected].home[0]>-70?'medical':'fire')).map(([key,v])=>`<option value="${key}" ${r.type===key?'selected':''}>${v.label}</option>`).join('')}</select></label>${info?`<button class="removeVehicle" data-remove-vehicle>− Retirer ce moyen</button><p class="composerHint">Équipage : ${info.crew} · ${info.group==='medical'?'Remise sanitaire':'Remise incendie / appui'}</p>${['Front','Rear'].map(zone=>`<label>Gyrophares ${zone==='Front'?'avant':'arrière'}<select data-signal-${zone.toLowerCase()}>${signalZoneChoices(r.type).map(key=>`<option value="${key}" ${(r['signal'+zone]||r.signal)===key?'selected':''}>${labels[key]}</option>`).join('')}</select></label>`).join('')}${['FPTSR','FPTL','CCFL','CCF','CCF8000'].includes(r.type)?`<label class="equipmentOption"><input type="checkbox" data-foam ${r.foam?'checked':''}> Équipement mousse</label>`:''}${['FPTSR','EPA'].includes(r.type)?`<label class="equipmentOption"><input type="checkbox" data-lighting ${r.lighting?'checked':''}> ${r.type==='EPA'?'Éclairage nacelle':'Mât d’éclairage'}</label>`:''}<p class="composerHint">Signalisation orange et feux de pénétration conservés.</p>`:'<p class="composerHint">Choisissez un modèle ci-dessus pour ajouter un engin à cette place.</p>'}</section></div><p class="composerFeedback" role="status">${errors.join(' ')||'Composition compatible avec toutes les missions.'}</p><div class="composerActions">${onBack?`<button class="composerBack" data-back ${errors.length?'disabled':''}>← Enregistrer et revenir au brief</button>`:''}<button data-default>Composition initiale</button><button data-save ${errors.length?'disabled':''}>Enregistrer</button><button data-start ${errors.length?'disabled':''}>Nouvelle garde avec cette caserne</button></div><small class="composerFoot">Enregistrer actualise les engins en remise. Les autres changent à leur retour.</small>`;
 dialog.querySelector('[data-staff]').onchange=ev=>{guardSize=Math.max(4,Math.min(30,Math.round(Number(ev.target.value)||13)));draw();};dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.slot);draw();});dialog.querySelector('[data-type]').onchange=ev=>{if(ev.target.value){r.type=ev.target.value;r.signal=signalChoices(r.type)[0];r.signalFront=r.signalRear=r.signal;draw();}};const remove=dialog.querySelector('[data-remove-vehicle]');if(remove)remove.onclick=()=>{r.type='';r.signal='standard';draw();};for(const zone of ['Front','Rear']){const el=dialog.querySelector('[data-signal-'+zone.toLowerCase()+']');if(el)el.onchange=()=>{r['signal'+zone]=el.value;draw();};}for(const prop of ['signal','foam','lighting']){const el=dialog.querySelector('[data-'+prop+']');if(el)el.onchange=()=>{r[prop]=prop==='signal'?el.value:el.checked;draw();};}dialog.querySelector('[data-default]').onclick=()=>{rows=defaultComposition(fleet);guardSize=13;draw();};const save=()=>{const staffError=saveGuardSize(guardSize);if(staffError){dialog.querySelector('.composerFeedback').textContent=staffError;return false;}const staffApplied=configureCrew(state,guardSize);const result=saveComposition(rows,fleet);const applied=result.error?null:apply(result.rows);dialog.querySelector('.composerFeedback').textContent=result.error||(applied?`${applied.changed} changement(s) appliqué(s) · ${applied.pending?applied.pending+' en attente du retour en remise':'caserne à jour'}.`:'Enregistré · appliqué à la prochaine nouvelle garde.');if(!result.error)dialog.querySelector('.composerFeedback').textContent+=staffApplied?' Effectif mis à jour.':' Effectif différé jusqu’au retour des équipages et des SPV.';return !result.error;};dialog.querySelector('[data-save]').onclick=save;const back=dialog.querySelector('[data-back]');if(back)back.onclick=()=>{if(!save())return;dialog.close();setTimeout(onBack,0);};dialog.querySelector('[data-start]').onclick=()=>{if(!save())return;dialog.querySelector('.composerFeedback').textContent='La garde actuelle sera remplacée. Confirmer le démarrage ?';const b=dialog.querySelector('[data-start]');b.textContent='Confirmer la nouvelle garde';b.onclick=()=>{if(save())location.reload();};};
 }
 draw();dialog.showModal();return dialog;
}
